-- 03_relasi_index.sql: relasi antar tabel D3 dan index tambahan
-- Relasi ke tabel tribe lain (b2_register, auth.users) TIDAK di sini, tapi di 90_ditunda_auth_b2.sql.

begin;
set search_path = public;

alter table public.d3_attendance_audit_log add constraint d3_attendance_audit_log_attendance_id_fkey FOREIGN KEY (attendance_id) REFERENCES d3_attendances(id) ON DELETE SET NULL;
alter table public.d3_attendance_audit_log add constraint d3_attendance_audit_log_closing_id_fkey FOREIGN KEY (closing_id) REFERENCES d3_attendance_closings(id) ON DELETE SET NULL;
alter table public.d3_attendance_audit_log add constraint d3_attendance_audit_log_correction_id_fkey FOREIGN KEY (correction_id) REFERENCES d3_attendance_corrections(id) ON DELETE SET NULL;
alter table public.d3_attendance_corrections add constraint fk_d3_attendance_corrections_d3_attendances FOREIGN KEY (attendance_id) REFERENCES d3_attendances(id) ON DELETE CASCADE;
alter table public.d3_b2_employee_sources add constraint d3_b2_employee_sources_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES d3_employee(id) ON DELETE RESTRICT;
alter table public.d3_d1_department_mappings add constraint d3_d1_department_mappings_department_id_fkey FOREIGN KEY (department_id) REFERENCES d3_departments(id) ON DELETE RESTRICT;
alter table public.d3_d1_position_mappings add constraint d3_d1_position_mappings_position_id_fkey FOREIGN KEY (position_id) REFERENCES d3_positions(id) ON DELETE RESTRICT;
alter table public.d3_d1_position_mappings add constraint d3_d1_position_mappings_source_department_key_fkey FOREIGN KEY (source_department_key) REFERENCES d3_d1_department_mappings(source_department_key) ON DELETE RESTRICT;
alter table public.d3_employee add constraint employees_department_id_fkey FOREIGN KEY (department_id) REFERENCES d3_departments(id) ON DELETE RESTRICT;
alter table public.d3_employee add constraint employees_position_id_fkey FOREIGN KEY (position_id) REFERENCES d3_positions(id) ON DELETE RESTRICT;
alter table public.d3_employee add constraint fk_d3_employee_d3_departments FOREIGN KEY (department_id) REFERENCES d3_departments(id) ON DELETE SET NULL;
alter table public.d3_employee_audit_log add constraint d3_employee_audit_log_actor_employee_id_fkey FOREIGN KEY (actor_employee_id) REFERENCES d3_employee(id) ON DELETE SET NULL;
alter table public.d3_employee_certifications add constraint employee_certifications_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES d3_employee(id) ON DELETE CASCADE;
alter table public.d3_employee_directory_hidden add constraint d3_employee_directory_hidden_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES d3_employee(id) ON DELETE RESTRICT;
alter table public.d3_employee_feedback add constraint d3_employee_feedback_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES d3_employee(id) ON DELETE RESTRICT;
alter table public.d3_employee_feedback add constraint d3_employee_feedback_given_by_fkey FOREIGN KEY (given_by) REFERENCES d3_employee(id) ON DELETE RESTRICT;
alter table public.d3_employee_reporting add constraint d3_employee_reporting_manager_employee_id_fkey FOREIGN KEY (manager_employee_id) REFERENCES d3_employee(id) ON DELETE RESTRICT;
alter table public.d3_employee_reporting add constraint d3_employee_reporting_subordinate_employee_id_fkey FOREIGN KEY (subordinate_employee_id) REFERENCES d3_employee(id) ON DELETE RESTRICT;
alter table public.d3_employee_rewards add constraint d3_employee_rewards_approved_by_fkey FOREIGN KEY (approved_by) REFERENCES d3_employee(id) ON DELETE SET NULL;
alter table public.d3_employee_rewards add constraint d3_employee_rewards_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES d3_employee(id) ON DELETE RESTRICT;
alter table public.d3_employee_rewards add constraint d3_employee_rewards_proposed_by_fkey FOREIGN KEY (proposed_by) REFERENCES d3_employee(id) ON DELETE SET NULL;
alter table public.d3_employee_skills add constraint employee_skills_competency_id_fkey FOREIGN KEY (competency_id) REFERENCES d3_competencies(id) ON DELETE RESTRICT;
alter table public.d3_employee_skills add constraint employee_skills_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES d3_employee(id) ON DELETE CASCADE;
alter table public.d3_employee_sync_events add constraint d3_employee_sync_events_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES d3_employee(id) ON DELETE RESTRICT;
alter table public.d3_face_biometric_events add constraint d3_face_biometric_events_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES d3_employee(id) ON DELETE RESTRICT;
alter table public.d3_face_biometric_templates add constraint d3_face_biometric_templates_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES d3_employee(id) ON DELETE CASCADE;
alter table public.d3_feedback_reward_audit_log add constraint d3_feedback_reward_audit_log_actor_employee_id_fkey FOREIGN KEY (actor_employee_id) REFERENCES d3_employee(id) ON DELETE SET NULL;
alter table public.d3_feedback_reward_audit_log add constraint d3_feedback_reward_audit_log_target_employee_id_fkey FOREIGN KEY (target_employee_id) REFERENCES d3_employee(id) ON DELETE RESTRICT;
alter table public.d3_feedback_reward_notifications add constraint d3_feedback_reward_notifications_recipient_employee_id_fkey FOREIGN KEY (recipient_employee_id) REFERENCES d3_employee(id) ON DELETE CASCADE;
alter table private.d3_idle_sessions add constraint d3_idle_sessions_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES d3_employee(id) ON DELETE RESTRICT;
alter table public.d3_positions add constraint positions_department_id_fkey FOREIGN KEY (department_id) REFERENCES d3_departments(id) ON DELETE SET NULL;
alter table public.d3_ticket_attachments add constraint d3_ticket_attachments_ticket_id_fkey FOREIGN KEY (ticket_id) REFERENCES d3_tickets(id) ON DELETE CASCADE;
alter table public.d3_ticket_followups add constraint d3_ticket_followups_actor_employee_id_fkey FOREIGN KEY (actor_employee_id) REFERENCES d3_employee(id) ON DELETE RESTRICT;
alter table public.d3_ticket_followups add constraint d3_ticket_followups_ticket_id_fkey FOREIGN KEY (ticket_id) REFERENCES d3_tickets(id) ON DELETE CASCADE;
alter table public.d3_ticket_history add constraint d3_ticket_history_actor_employee_id_fkey FOREIGN KEY (actor_employee_id) REFERENCES d3_employee(id) ON DELETE RESTRICT;
alter table public.d3_ticket_history add constraint d3_ticket_history_ticket_id_fkey FOREIGN KEY (ticket_id) REFERENCES d3_tickets(id) ON DELETE CASCADE;
alter table public.d3_tickets add constraint d3_tickets_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES d3_employee(id) ON DELETE RESTRICT;
alter table public.d3_user_access add constraint d3_user_access_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES d3_employee(id) ON DELETE RESTRICT;

CREATE INDEX d3_attendance_audit_log_created_at_idx ON public.d3_attendance_audit_log USING btree (created_at DESC);
CREATE INDEX d3_attendance_audit_log_target_idx ON public.d3_attendance_audit_log USING btree (target_b2_register_id, created_at DESC);
CREATE INDEX d3_attendance_closings_period_idx ON public.d3_attendance_closings USING btree (period_start, period_end, status);
CREATE INDEX d3_attendance_corrections_attendance_id_idx ON public.d3_attendance_corrections USING btree (attendance_id);
CREATE INDEX d3_attendance_corrections_requested_by_b2_register_id_idx ON public.d3_attendance_corrections USING btree (requested_by_b2_register_id);
CREATE INDEX d3_attendance_corrections_reviewed_by_b2_register_id_idx ON public.d3_attendance_corrections USING btree (reviewed_by_b2_register_id) WHERE (reviewed_by_b2_register_id IS NOT NULL);
CREATE INDEX d3_attendances_b2_register_id_date_idx ON public.d3_attendances USING btree (b2_register_id, date DESC);
CREATE INDEX d3_b2_employee_sources_employee_id_idx ON public.d3_b2_employee_sources USING btree (employee_id);
CREATE INDEX d3_d1_position_mappings_active_idx ON public.d3_d1_position_mappings USING btree (is_active, position_id);
CREATE INDEX idx_employees_employee_id ON public.d3_employee USING btree (employee_id);
CREATE INDEX idx_d3_employee_audit_log_employee ON public.d3_employee_audit_log USING btree (employee_record_id, created_at DESC);
CREATE INDEX d3_employee_feedback_employee_date_idx ON public.d3_employee_feedback USING btree (employee_id, date);
CREATE INDEX d3_employee_feedback_given_by_date_idx ON public.d3_employee_feedback USING btree (given_by, date);
CREATE INDEX d3_feedback_employee_filter_idx ON public.d3_employee_feedback USING btree (employee_id, date DESC, follow_up_status);
CREATE INDEX d3_employee_reporting_manager_active_idx ON public.d3_employee_reporting USING btree (manager_employee_id, is_active);
CREATE INDEX d3_employee_reporting_subordinate_active_idx ON public.d3_employee_reporting USING btree (subordinate_employee_id, is_active);
CREATE UNIQUE INDEX d3_employee_reporting_unique_active_pair_idx ON public.d3_employee_reporting USING btree (manager_employee_id, subordinate_employee_id) WHERE (is_active = true);
CREATE INDEX d3_employee_rewards_employee_date_idx ON public.d3_employee_rewards USING btree (employee_id, date);
CREATE INDEX d3_reward_employee_filter_idx ON public.d3_employee_rewards USING btree (employee_id, date DESC, status, reward_type);
CREATE INDEX d3_employee_sync_events_created_at_idx ON public.d3_employee_sync_events USING btree (created_at DESC);
CREATE INDEX d3_face_biometric_events_employee_verified_idx ON public.d3_face_biometric_events USING btree (employee_id, verified_at DESC);
CREATE INDEX d3_feedback_notifications_recipient_idx ON public.d3_feedback_reward_notifications USING btree (recipient_employee_id, created_at DESC);
CREATE INDEX d3_feedback_notifications_unread_idx ON public.d3_feedback_reward_notifications USING btree (recipient_employee_id) WHERE (read_at IS NULL);
CREATE INDEX d3_idle_sessions_auth_user_id_idx ON private.d3_idle_sessions USING btree (auth_user_id, expires_at);
CREATE INDEX d3_idle_sessions_expires_at_idx ON private.d3_idle_sessions USING btree (expires_at);
CREATE INDEX d3_ticket_attachments_ticket_idx ON public.d3_ticket_attachments USING btree (ticket_id);
CREATE INDEX d3_ticket_followups_actor_idx ON public.d3_ticket_followups USING btree (actor_employee_id);
CREATE INDEX d3_ticket_followups_ticket_date_idx ON public.d3_ticket_followups USING btree (ticket_id, follow_up_at DESC);
CREATE INDEX d3_ticket_history_actor_idx ON public.d3_ticket_history USING btree (actor_employee_id);
CREATE INDEX d3_ticket_history_ticket_created_idx ON public.d3_ticket_history USING btree (ticket_id, created_at DESC);
CREATE INDEX d3_tickets_employee_created_idx ON public.d3_tickets USING btree (employee_id, created_at DESC);
CREATE INDEX d3_tickets_open_due_at_idx ON public.d3_tickets USING btree (due_at) WHERE (status <> ALL (ARRAY['RESOLVED'::d3_ticket_status, 'REJECTED'::d3_ticket_status]));
CREATE INDEX d3_tickets_priority_created_idx ON public.d3_tickets USING btree (priority, created_at DESC);
CREATE INDEX d3_tickets_status_created_idx ON public.d3_tickets USING btree (status, created_at DESC);
CREATE INDEX d3_user_access_employee_id_idx ON public.d3_user_access USING btree (employee_id);

commit;
